CREATE OR REPLACE FUNCTION public.add_shirt_campaign_lot(p_campaign_id UUID, p_quantity INTEGER, p_unit_cost NUMERIC, p_supplier TEXT DEFAULT NULL, p_purchase_date DATE DEFAULT CURRENT_DATE, p_notes TEXT DEFAULT NULL) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_user_id UUID := auth.uid(); v_campaign public.shirt_campaigns%ROWTYPE; v_lot_id UUID; v_transaction_id UUID; v_total_cost NUMERIC(12,2); BEGIN IF v_user_id IS NULL THEN RAISE EXCEPTION 'Usuario nao autenticado'; END IF; IF p_quantity IS NULL OR p_quantity <= 0 THEN RAISE EXCEPTION 'A quantidade do lote deve ser maior que zero'; END IF; IF p_unit_cost IS NULL OR p_unit_cost < 0 THEN RAISE EXCEPTION 'O custo unitario nao pode ser negativo'; END IF; SELECT * INTO v_campaign FROM public.shirt_campaigns WHERE id = p_campaign_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Campanha nao encontrada'; END IF; IF NOT (has_role(v_user_id, 'admin'::app_role) OR (has_role(v_user_id, 'diretoria'::app_role) AND v_campaign.society_id = get_user_society_id(v_user_id))) THEN RAISE EXCEPTION 'Usuario sem permissao para esta campanha'; END IF; v_total_cost := ROUND(p_quantity * p_unit_cost, 2); INSERT INTO public.transactions (description, amount, type, date, created_by, origin, reference_type, society_id) VALUES ('Novo lote de camisas - ' || v_campaign.name || ' - ' || p_quantity || ' unidades', v_total_cost, 'saida', COALESCE(p_purchase_date, CURRENT_DATE), v_user_id, 'automatic', 'shirt_campaign_purchase', v_campaign.society_id) RETURNING id INTO v_transaction_id; INSERT INTO public.shirt_campaign_lots (campaign_id, quantity, unit_cost, total_cost, supplier, purchase_date, notes, transaction_id, society_id, created_by) VALUES (p_campaign_id, p_quantity, p_unit_cost, v_total_cost, NULLIF(TRIM(COALESCE(p_supplier, '')), ''), COALESCE(p_purchase_date, CURRENT_DATE), NULLIF(TRIM(COALESCE(p_notes, '')), ''), v_transaction_id, v_campaign.society_id, v_user_id) RETURNING id INTO v_lot_id; UPDATE public.shirt_campaigns SET purchased_quantity = purchased_quantity + p_quantity, total_purchase_cost = ROUND(total_purchase_cost + v_total_cost, 2), unit_cost = CASE WHEN (purchased_quantity + p_quantity) > 0 THEN ROUND((total_purchase_cost + v_total_cost) / (purchased_quantity + p_quantity), 2) ELSE unit_cost END, updated_at = now() WHERE id = p_campaign_id; RETURN v_lot_id; END; $function$;